def _cart_position(event, item, membership=None, subevent=None):
    return CartPosition(event=event, item=item, price=Decimal('23.00'), used_membership=membership, subevent=subevent)


def _order_with_membership(event, customer, item, membership, subevent=None):
    order = Order.objects.create(
        event=event, customer=customer, status=Order.STATUS_PAID, code=f"M{Order.objects.count()}",
        email="dummy@example.org", datetime=now(), expires=now() + timedelta(days=10), total=Decimal('23.00'),
        locale='en', testmode=membership.testmode, sales_channel=event.organizer.sales_channels.get(identifier="web"),
    )
    OrderPosition.objects.create(order=order, item=item, subevent=subevent, price=Decimal('23.00'),
                                 used_membership=membership)
    return order


